import argparse
import json
import shutil
import subprocess
import sys
from pathlib import Path

from fastapi_rpckit.codegen import (
    PythonClientOptions,
    render_python_client,
    write_files,
)

_REPO_ROOT = Path(__file__).resolve().parents[4]
_PACKAGE = "gateway_rpc_client"
_DEFAULT_OUTPUT = _REPO_ROOT / "generated" / _PACKAGE / "src" / _PACKAGE
_RUFF = shutil.which("ruff", path=str(Path(sys.executable).parent)) or "ruff"

_AUTHENTICATED_CLIENT = """# Generated by gateway-server from gateway.openrpc.json.
# Do not edit this file manually.

from uuid import UUID

from gateway_rpc_client.client import GatewayRpcClient


async def connect_gateway(base_url: str, *, token: str) -> GatewayRpcClient:
    scheme, separator, address = base_url.rstrip("/").partition("://")
    gateway_url = f"{scheme.replace('http', 'ws', 1)}{separator}{address}"
    connection = GatewayRpcClient.connect(
        gateway_url=gateway_url,
        headers={"Authorization": f"Bearer {token}"},
        lazy=True,
    )
    return await connection


async def connect_room(
    base_url: str,
    room_id: UUID,
    *,
    token: str,
) -> GatewayRpcClient:
    scheme, separator, address = base_url.rstrip("/").partition("://")
    gateway_url = f"{scheme.replace('http', 'ws', 1)}{separator}{address}"
    connection = GatewayRpcClient.connect(
        gateway_url=gateway_url,
        room_id=str(room_id),
        headers={"Authorization": f"Bearer {token}"},
        lazy=True,
    )
    return await connection
"""


def generate(schema_path: Path, output_directory: Path, *, check: bool = False) -> bool:
    """Generate the Gateway RPC client with fastapi-rpckit's bundled runtime."""
    document = json.loads(schema_path.read_text(encoding="utf-8"))
    options = PythonClientOptions(
        package=_PACKAGE,
        client_name="GatewayRpcClient",
        source=schema_path.name,
        with_transport="websocket",
        extra_files={"authenticated.py": _AUTHENTICATED_CLIENT},
        extra_exports={
            "connect_gateway": "authenticated",
            "connect_room": "authenticated",
        },
    )
    rendered = dict(render_python_client(document, options))
    formatted = {
        path: _ruff_format(path, _separate_header(content))
        if path.endswith(".py")
        else content
        for path, content in rendered.items()
    }
    return bool(write_files(output_directory, formatted, check=check))


def _separate_header(content: str) -> str:
    lines = content.splitlines()
    if len(lines) >= 2 and lines[0].startswith("# Generated by "):
        while len(lines) > 2 and not lines[2]:
            lines.pop(2)
        lines.insert(2, "")
    return "\n".join(lines) + "\n"


def _ruff_format(filename: str, content: str) -> str:
    # The SDK supports Python 3.13. A 3.14 target would remove forward-reference
    # quotes that its generated dataclasses still need on 3.13.
    ruff_options = ["--target-version", "py313", "--stdin-filename", filename, "-"]
    sorted_content = subprocess.run(
        [_RUFF, "check", "--fix-only", *ruff_options],
        cwd=_REPO_ROOT,
        input=content,
        capture_output=True,
        text=True,
        check=True,
    ).stdout
    return subprocess.run(
        [_RUFF, "format", *ruff_options],
        cwd=_REPO_ROOT,
        input=sorted_content,
        capture_output=True,
        text=True,
        check=True,
    ).stdout


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate the typed Gateway RPC client"
    )
    parser.add_argument("schema", type=Path)
    parser.add_argument("--output", type=Path, default=_DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true")
    arguments = parser.parse_args()
    changed = generate(arguments.schema, arguments.output, check=arguments.check)
    if arguments.check and changed:
        parser.error("generated client is out of date")


if __name__ == "__main__":
    main()
